   362→<script>
   363→
   364→function getLetterLocal(n) {
   365→    if (n >= 90) return ['A','#10b981'];
   366→    if (n >= 75) return ['B','#2563eb'];
   367→    if (n >= 60) return ['C','#f6af23'];
   368→    if (n >= 50) return ['D','#f97316'];
   369→    return ['E','#ef4444'];
   370→}
   371→
   372→function updateGradeDisplay(input, sid) {
   373→    const val = parseFloat(input.value);
   374→    const span = document.getElementById(`letter_${sid}`);
   375→    if (isNaN(val) || input.value === '') {
   376→        span.textContent = '—';
   377→        span.style.background = 'var(--card-border)';
   378→        span.style.color = 'var(--text-muted)';
   379→        input.style.borderColor = 'var(--card-border)';
   380→    } else {
   381→        const [letter, color] = getLetterLocal(Math.min(100, Math.max(0, val)));
   382→        span.textContent = letter;
   383→        span.style.background = color;
   384→        span.style.color = '#fff';
   385→        input.style.borderColor = color;
   386→        input.style.color = color;
   387→    }
   388→    updateStats();
   389→    updateAvg();
   390→}
   391→
   392→function updateStats() {
   393→    let a=0,b=0,c=0,d=0;
   394→    document.querySelectorAll('.grade-input').forEach(inp => {
   395→        const v = parseFloat(inp.value);
   396→        if (isNaN(v)) return;
   397→        if (v>=90) a++; else if (v>=75) b++; else if (v>=60) c++; else d++;
   398→    });
   399→    const sa=document.getElementById('statA'),sb=document.getElementById('statB'),sc=document.getElementById('statC'),sd=document.getElementById('statD');
   400→    if(sa) sa.textContent=a;
   401→    if(sb) sb.textContent=b;
   402→    if(sc) sc.textContent=c;
   403→    if(sd) sd.textContent=d;
   404→}
   405→
   406→function updateAvg() {
   407→    const vals = [...document.querySelectorAll('.grade-input')]
   408→        .map(i => parseFloat(i.value))
   409→        .filter(v => !isNaN(v));
   410→    const el = document.getElementById('avgDisplay');
   411→    if (!el) return;
   412→    if (vals.length === 0) { el.textContent = '—'; return; }
   413→    const avg = (vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(1);
   414→    el.textContent = avg + ` (${getLetterLocal(avg)[0]})`;
   415→    el.style.color = getLetterLocal(parseFloat(avg))[1];
   416→}
   417→
   418→function autoFill() {
   419→    document.querySelectorAll('.grade-input').forEach(inp => {
   420→        const v = Math.floor(Math.random() * 40) + 60;
   421→        inp.value = v;
   422→        const sid = inp.id.replace('grade_','');
   423→        updateGradeDisplay(inp, sid);
   424→    });
   425→}
   426→
   427→function clearAll() {
   428→    document.querySelectorAll('.grade-input').forEach(inp => {
   429→        inp.value = '';
   430→        const sid = inp.id.replace('grade_','');
   431→        updateGradeDisplay(inp, sid);
   432→    });
   433→}
   434→
   435→async function submitGrades(e) {
   436→    e.preventDefault();
   437→    const inputs = [...document.querySelectorAll('.grade-input')];
   438→    const filled = inputs.filter(i => i.value !== '').length;
   439→    if (filled === 0) {
   440→        window.showToast('Belum ada nilai yang diisi!', 'warning');
   441→        return;
   442→    }
   443→    const btn = document.getElementById('submitGradeBtn');
   444→    btn.disabled = true;
   445→    btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Menyimpan...';
   446→
   447→    const fd = new FormData();
   448→    fd.append('_token', document.querySelector('meta[name=csrf-token]').content);
   449→    fd.append('course_id', document.querySelector('[name=course_id]').value);
   450→    fd.append('jenis',     document.querySelector('[name=jenis]').value);
   451→    inputs.forEach(inp => {
   452→        if (inp.value !== '') {
   453→            const sid = inp.id.replace('grade_', '');
   454→            fd.append(`grades[${sid}]`, inp.value);
   455→        }
   456→    });
   457→
   458→    try {
   459→        const res  = await fetch('{{ route("guru.grades.storeBatch") }}', { method: 'POST', body: fd });
   460→        const data = await res.json();
   461→        if (data.success) {
   462→            window.showToast(data.message || 'Nilai berhasil disimpan!', 'success');
   463→        } else {
   464→            window.showToast(data.message || 'Gagal menyimpan nilai.', 'error');
   465→        }
   466→    } catch (err) {
   467→        window.showToast('Terjadi kesalahan jaringan. Coba lagi.', 'error');
   468→    } finally {
   469→        btn.disabled = false;
   470→        btn.innerHTML = '<i class="bi bi-save me-2"></i>Simpan Nilai';
   471→    }
   472→}
   473→
   474→// Init stats on page load
   475→document.addEventListener('DOMContentLoaded', function() {
   476→    document.querySelectorAll('.grade-input').forEach(inp => {
   477→        if (inp.value !== '') {
   478→            const sid = inp.id.replace('grade_','');
   479→            updateGradeDisplay(inp, sid);
   480→        }
   481→    });
   482→});
   483→</script>
